<?php
$t = array();
$t[1] = 'أَيْ اِنْصَدَعَتْ , وَتَفَطَّرَتْ بِالْغَمَامِ , وَالْغَمَام مِثْل السَّحَاب الْأَبْيَض . وَكَذَا رَوَى أَبُو صَالِح عَنْ اِبْن عَبَّاس . وَرُوِيَ عَنْ عَلِيّ عَلَيْهِ السَّلَام قَالَ : تُشَقُّ مِنْ الْمَجَرَّة . وَقَالَ : الْمَجَرَّة بَاب السَّمَاء . وَهَذَا مِنْ أَشْرَاط السَّاعَة وَعَلَامَاتهَا .';
$t[2] = 'أَيْ سَمِعْت , وَحُقَّ لَهَا أَنْ تَسْمَع . رُوِيَ مَعْنَاهُ عَنْ اِبْن عَبَّاس وَمُجَاهِد وَغَيْرهمَا ; وَمِنْهُ قَوْله صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : &quot; مَا أَذِنَ اللَّه لِشَيْءٍ كَإِذْنِهِ لِنَبِيٍّ يَتَغَنَّى بِالْقُرْآنِ &quot; أَيْ مَا اِسْتَمَعَ اللَّه لِشَيْءٍ قَالَ الشَّاعِر : صُمٌّ إِذَا سَمِعُوا خَيْرًا ذُكِرْت بِهِ وَإِنْ ذُكِرْت بِسُوءٍ عِنْدهمْ أَذِنُوا أَيْ سَمِعُوا . وَقَالَ قُعْنُب اِبْن أُمّ صَاحِب : إِنْ يَأْذَنُوا رِيبَةً طَارُوا بِهَا فَرَحًا وَمَا هُمْ أَذِنُوا مِنْ صَالِح دَفَنُوا وَقِيلَ : الْمَعْنَى وَحَقَّقَ اللَّه عَلَيْهَا الِاسْتِمَاع لِأَمْرِهِ بِالِانْشِقَاقِ . وَقَالَ الضَّحَّاك : حُقَّتْ : أَطَاعَتْ , وَحُقَّ لَهَا أَنْ تُطِيع رَبّهَا , لِأَنَّهُ خَلَقَهَا ; يُقَال : فُلَان مَحْقُوق بِكَذَا . وَطَاعَة السَّمَاء : بِمَعْنَى أَنَّهَا لَا تَمْتَنِع مِمَّا أَرَادَ اللَّه بِهَا , وَلَا يَبْعُد خَلْق الْحَيَاة فِيهَا حَتَّى تُطِيع وَتُجِيب . وَقَالَ قَتَادَة : حُقَّ لَهَا أَنْ تَفْعَل ذَلِكَ ; وَمِنْهُ قَوْل كُثَيِّر : فَإِنْ تَكُنْ الْعُتْبَى فَأَهْلًا وَمَرْحَبًا وَحُقَّتْ لَهَا الْعُتْبَى لَدَيْنَا وَقَلَّتْ';
$t[3] = 'أَيْ بُسِطَتْ وَدُكَّتْ جِبَالهَا . قَالَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( تُمَدُّ مَدَّ الْأَدِيم ) لِأَنَّ الْأَدِيم إِذَا مُدَّ زَالَ كُلُّ اِنْثِنَاء فِيهِ وَامْتَدَّ وَاسْتَوَى . قَالَ اِبْن عَبَّاس وَابْن مَسْعُود : وَيُزَاد وَسِعَتهَا كَذَا وَكَذَا ; لِوُقُوفِ الْخَلَائِق عَلَيْهَا لِلْحِسَابِ حَتَّى لَا يَكُون لِأَحَدٍ مِنْ الْبَشَر إِلَّا مَوْضِع قَدَمه , لِكَثْرَةِ الْخَلَائِق فِيهَا . وَقَدْ مَضَى فِي سُورَة &quot; إِبْرَاهِيم &quot; أَنَّ الْأَرْض تُبَدَّل بِأَرْضٍ أُخْرَى وَهِيَ السَّاهِرَة فِي قَوْل اِبْن عَبَّاس عَلَى مَا تَقَدَّمَ عَنْهُ';
$t[4] = 'أَيْ أَخْرَجَتْ أَمْوَاتهَا , وَتَخَلَّتْ عَنْهُمْ . وَقَالَ اِبْن جُبَيْر : أَلْقَتْ مَا فِي بَطْنهَا مِنْ الْمَوْتَى , وَتَخَلَّتْ مِمَّنْ عَلَى ظَهْرِهَا مِنْ الْأَحْيَاء . وَقِيلَ : أَلْقَتْ مَا فِي بَطْنهَا كُنُوزهَا وَمَعَادِنهَا , وَتَخَلَّتْ مِنْهَا . أَيْ خَلَّا جَوْفهَا , فَلَيْسَ فِي بَطْنهَا شَيْء , وَذَلِكَ يُؤْذِن بِعَظَمِ الْأَمْر , كَمَا تُلْقِي الْحَامِل مَا فِي بَطْنهَا عِنْد الشِّدَّة . وَقِيلَ : تَخَلَّتْ مِمَّا عَلَى ظَهْرهَا مِنْ جِبَالهَا وَبِحَارهَا . وَقِيلَ : أَلْقَتْ مَا اُسْتُوْدِعَتْ , وَتَخَلَّتْ مِمَّا اُسْتُحْفِظَتْ ; لِأَنَّ اللَّه تَعَالَى اِسْتَوْدَعَهَا عِبَاده أَحْيَاء وَأَمْوَاتًا , وَاسْتَحْفَظَهَا بِلَاده مُزَارَعَة وَأَقْوَاتًا .';
$t[5] = 'أَيْ فِي إِلْقَاء مَوْتَاهَا

أَيْ وَحُقَّ لَهَا أَنْ تَسْمَع أَمْرَهُ . وَاخْتُلِفَ فِي جَوَاب &quot; إِذَا &quot; فَقَالَ الْفَرَّاء : &quot; أَذِنَتْ &quot; . وَالْوَاو زَائِدَة , وَكَذَلِكَ &quot; وَأَلْقَتْ &quot; . اِبْن الْأَنْبَارِيّ : قَالَ بَعْض الْمُفَسِّرِينَ : جَوَاب &quot; إِذَا السَّمَاء انْشَقَّتْ &quot; &quot; أَذِنَتْ &quot; , وَزَعَمَ أَنَّ الْوَاو مُقْحَمَة وَهَذَا غَلَط ; لِأَنَّ الْعَرَب لَا تُقْحِم الْوَاو إِلَّا مَعَ &quot; حَتَّى - إِذَا &quot; كَقَوْلِهِ تَعَالَى : &quot; حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابهَا &quot; [ الزُّمَر : 71 ] وَمَعَ &quot; لَمَّا &quot; كَقَوْلِهِ تَعَالَى : &quot; فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ . وَنَادَيْنَاهُ &quot; [ الصَّافَّات : 103 - 104 ] مَعْنَاهُ &quot; نَادَيْنَاهُ &quot; وَالْوَاو لَا تُقْحَم مَعَ غَيْر هَذَيْنِ . وَقِيلَ : الْجَوَاب فَاء مُضْمَرَة كَأَنَّهُ قَالَ : &quot; إِذَا السَّمَاء انْشَقَّتْ &quot; فَيَا أَيُّهَا الْإِنْسَان إِنَّك كَادِح . وَقِيلَ : جَوَابهَا مَا دَلَّ عَلَيْهِ &quot; فَمُلَاقِيه &quot; أَيْ إِذَا السَّمَاء اِنْشَقَّتْ لَاقَى الْإِنْسَان كَدْحه . وَقِيلَ : فِيهِ تَقْدِيم وَتَأْخِير , أَيْ &quot; يَا أَيُّهَا الْإِنْسَان إِنَّك كَادِح إِلَى رَبّك كَدْحًا فَمُلَاقِيه &quot; &quot; إِذَا السَّمَاء اِنْشَقَّتْ &quot; . قَالَهُ الْمُبَرِّد . وَعَنْهُ أَيْضًا : الْجَوَاب &quot; فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ &quot; وَهُوَ قَوْل الْكِسَائِيّ ; أَيْ إِذَا السَّمَاء انْشَقَّتْ فَمَنْ أُوتِيَ كِتَابه بِيَمِينِهِ فَحُكْمه كَذَا . قَالَ أَبُو جَعْفَر النَّحَّاس : وَهَذَا أَصَحّ مَا قِيلَ فِيهِ وَأَحْسَنه . قِيلَ : هُوَ بِمَعْنَى اذْكُرْ &quot; إِذَا السَّمَاء اِنْشَقَّتْ &quot; . وَقِيلَ : الْجَوَاب مَحْذُوف لِعِلْمِ الْمُخَاطَبِينَ بِهِ ; أَيْ إِذَا كَانَتْ هَذِهِ الْأَشْيَاء عَلِمَ الْمُكَذِّبُونَ بِالْبَعْثِ ضَلَالَتهمْ وَخُسْرَانهمْ . وَقِيلَ : تَقَدَّمَ مِنْهُمْ سُؤَال عَنْ وَقْت الْقِيَامَة , فَقِيلَ لَهُمْ : إِذَا ظَهَرَتْ أَشْرَاطهَا كَانَتْ الْقِيَامَة , فَرَأَيْتُمْ عَاقِبَة تَكْذِيبكُمْ بِهَا . وَالْقُرْآن كَالْآيَةِ الْوَاحِدَة فِي دَلَالَة الْبَعْض عَلَى الْبَعْض . وَعَنْ الْحَسَن : إِنَّ قَوْله &quot; إِذَا السَّمَاء اِنْشَقَّتْ &quot; قَسَم . وَالْجُمْهُور عَلَى خِلَاف قَوْله مِنْ أَنَّهُ خَبَر وَلَيْسَ بِقَسَمٍ .';
$t[6] = 'الْمُرَاد بِالْإِنْسَانِ الْجِنْس أَيْ يَا اِبْن آدَم . وَكَذَا رَوَى سَعِيد عَنْ قَتَادَة : يَا اِبْن آدَم , إِنَّ كَدْحك لَضَعِيف , فَمَنْ اِسْتَطَاعَ أَنْ يَكُون كَدْحه فِي طَاعَة اللَّه فَلْيَفْعَلْ وَلَا قُوَّة إِلَّا بِاَللَّهِ . وَقِيلَ : هُوَ مُعَيَّن , قَالَ مُقَاتِل : يَعْنِي الْأَسْوَد بْن عَبْد الْأَسَد وَيُقَال : يَعْنِي أُبَيّ بْن خَلَف . وَيُقَال : يَعْنِي جَمِيع الْكُفَّار , أَيّهَا الْكَافِر إِنَّك كَادِح . وَالْكَدْح فِي كَلَام الْعَرَب : الْعَمَل وَالْكَسْب ; قَالَ اِبْن مُقْبِل : وَمَا الدَّهْر إِلَّا تَارَتَانِ فَمِنْهُمَا أَمُوت وَأُخْرَى أَبْتَغِي الْعَيْش أَكْدَح وَقَالَ آخَر : وَمَضَتْ بَشَاشَة كُلّ عَيْش صَالِح وَبَقِيت أَكْدَح لِلْحَيَاةِ وَأَنْصِبُ أَيْ أَعْمَل . وَرَوَى الضَّحَّاك عَنْ اِبْن عَبَّاس : &quot; إِنَّك كَادِح &quot; أَيْ رَاجِع &quot; إِلَى رَبّك كَدْحًا أَيْ رُجُوعًا لَا مَحَالَة

أَيْ مُلَاقٍ رَبّك . وَقِيلَ : مُلَاقٍ عَمَلك . الْقُتَبِيّ &quot; إِنَّك كَادِح &quot; أَيْ عَامِل نَاصِب فِي مَعِيشَتك إِلَى لِقَاء رَبّك . وَالْمُلَاقَاة بِمَعْنَى اللِّقَاء أَنْ تَلْقَى رَبّك بِعَمَلِك . وَقِيلَ أَيْ تُلَاقِي كِتَاب عَمَلك ; لِأَنَّ الْعَمَل قَدْ اِنْقَضَى وَلِهَذَا قَالَ :';
$t[7] = 'قَوْله تَعَالَى : &quot; فَأَمَّا مَنْ أُوتِيَ كِتَابه بِيَمِينِهِ &quot; وَهُوَ الْمُؤْمِن';
$t[8] = 'لَا مُنَاقَشَة فِيهِ . كَذَا رُوِيَ عَنْ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ مِنْ حَدِيث عَائِشَة قَالَتْ : قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( مَنْ حُوسِبَ يَوْم الْقِيَامَة عُذِّبَ ) قَالَتْ : فَقُلْت يَا رَسُول اللَّه أَلَيْسَ قَدْ قَالَ اللَّه &quot; فَأَمَّا مَنْ أُوتِيَ كِتَابه بِيَمِينِهِ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا &quot; فَقَالَ : &quot; لَيْسَ ذَاكَ الْحِسَاب ; إِنَّمَا ذَلِكَ الْعَرْض , مَنْ نُوقِشَ الْحِسَاب يَوْم الْقِيَامَة عُذِّبَ ) أَخْرَجَهُ الْبُخَارِيّ وَمُسْلِم وَالتِّرْمِذِيّ . وَقَالَ حَدِيث حَسَن صَحِيح .';
$t[9] = 'أَزْوَاجه فِي الْجَنَّة مِنْ الْحُور الْعِين &quot; مَسْرُورًا &quot; أَيْ مُغْتَبِطًا قَرِير الْعَيْن . وَيُقَال إِنَّهَا نَزَلَتْ فِي أَبِي سَلَمَة بْن عَبْد الْأَسَد , هُوَ أَوَّل مَنْ هَاجَرَ مِنْ مَكَّة إِلَى الْمَدِينَة . وَقِيلَ : إِلَى أَهْله الَّذِينَ كَانُوا لَهُ فِي الدُّنْيَا , لِيُخْبِرَهُمْ بِخَلَاصِهِ وَسَلَامَته . وَالْأَوَّل قَوْل قَتَادَة . أَيْ إِلَى أَهْله الَّذِينَ قَدْ أَعَدَّهُمْ اللَّه لَهُ فِي الْجَنَّة .';
$t[10] = 'نَزَلَتْ فِي الْأَسْوَد بْن عَبْد الْأَسَد أَخِي أَبِي سَلَمَة قَالَ اِبْن عَبَّاس . ثُمَّ هِيَ عَامَّة فِي كُلّ مُؤْمِن وَكَافِر . قَالَ اِبْن عَبَّاس : يَمُدُّ يَدَهُ الْيُمْنَى لِيَأْخُذ كِتَابه فَيَجْذِبهُ مَلَك , فَيَخْلَع يَمِينه , فَيَأْخُذ كِتَابه بِشِمَالِهِ مِنْ وَرَاء ظَهْره . وَقَالَ قَتَادَة وَمُقَاتِل : يُفَكّ أَلْوَاح صَدْره وَعِظَامه ثُمَّ تُدْخَل يَده وَتُخْرَج مِنْ ظَهْره , فَيَأْخُذ كِتَابه كَذَلِكَ .';
$t[11] = 'أَيْ بِالْهَلَاكِ فَيَقُول : يَا وَيْلَاه , يَا ثُبُورَاه .';
$t[12] = 'أَيْ وَيَدْخُل النَّار حَتَّى يَصْلَى بَحَرِّهَا . وَقَرَأَ الْحَرَمِيَّان وَابْن عَامِر وَالْكِسَائِيّ &quot; وَيُصَلَّى &quot; بِضَمِّ الْيَاء وَفَتْح الصَّاد , وَتَشْدِيد اللَّام , كَقَوْلِهِ تَعَالَى : &quot; ثُمَّ الْجَحِيم صَلُّوهُ &quot; [ الْحَاقَّة : 31 ] وَقَوْله : &quot; وَتَصْلِيَة جَحِيم &quot; [ الْوَاقِعَة : 94 ] . الْبَاقُونَ &quot; وَيَصْلَى &quot; بِفَتْحِ الْيَاء مُخَفَّفًا , فِعْل لَازِم غَيْر مُتَعَدٍّ ; لِقَوْلِهِ : &quot; إِلَّا مَنْ هُوَ صَالِ الْجَحِيم &quot; [ الصَّافَّات : 163 ] وَقَوْله : &quot; يَصْلَى النَّار الْكُبْرَى &quot; [ الْأَعْلَى : 12 ] وَقَوْله &quot; ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيم &quot; [ الْمُطَفِّفِينَ : 16 ] . وَقِرَاءَة ثَالِثَة رَوَاهَا أَبَان عَنْ عَاصِم وَخَارِجَة عَنْ نَافِع وَإِسْمَاعِيل الْمَكِّيّ عَنْ اِبْن كَثِير &quot; وَيُصْلَى &quot; بِضَمِّ الْيَاء وَإِسْكَان الصَّاد وَفَتْح اللَّام مُخَفَّفًا ; كَمَا قُرِئَ &quot; وَسَيُصْلَوْنَ &quot; بِضَمِّ الْيَاء , وَكَذَلِكَ فِي &quot; الْغَاشِيَة &quot; قَدْ قُرِئَ أَيْضًا : &quot; تُصْلَى نَارًا &quot; وَهُمَا لُغَتَانِ صَلَى وَأَصْلَى ; كَقَوْلِهِ : &quot; نَزَلَ . وَأَنْزَلَ &quot; .';
$t[13] = 'أَيْ فِي الدُّنْيَا

قَالَ اِبْن زَيْد : وَصَفَ اللَّه أَهْل الْجَنَّة بِالْمَخَافَةِ وَالْحُزْن وَالْبُكَاء وَالشَّفَقَة فِي الدُّنْيَا فَأَعْقَبَهُمْ بِهِ النَّعِيم وَالسُّرُور فِي الْآخِرَة , وَقَرَأَ قَوْل اللَّه تَعَالَى : &quot; إِنَّا كُنَّا قَبْل فِي أَهْلنَا مُشْفِقِينَ فَمَنَّ اللَّه عَلَيْنَا وَوَقَانَا عَذَاب السَّمُوم &quot; . قَالَ : وَوَصَفَ أَهْل النَّار بِالسُّرُورِ فِي الدُّنْيَا وَالضَّحِك فِيهَا وَالتَّفَكُّه . فَقَالَ : &quot; إِنَّهُ كَانَ فِي أَهْله مَسْرُورًا &quot;';
$t[14] = 'أَيْ لَنْ يَرْجِع حَيًّا مَبْعُوثًا فَيُحَاسَب , ثُمَّ يُثَاب أَوْ يُعَاقَب . يُقَال : حَارَ يَحُور إِذَا رَجَعَ ; قَالَ لَبِيد : وَمَا الْمَرْء إِلَّا كَالشِّهَابِ وُضُوئِهِ يَحُور رَمَادًا بَعْد إِذْ هُوَ سَاطِع وَقَالَ عِكْرِمَة وَدَاوُد بْن أَبِي هِنْد , يَحُور كَلِمَة بِالْحَبَشِيَّةِ , وَمَعْنَاهَا يَرْجِع . وَيَجُوز أَنْ تَتَّفِقَ الْكَلِمَتَانِ فَإِنَّهُمَا كَلِمَة اِشْتِقَاق ; وَمِنْهُ الْخُبْز الْحُوَارَى ; لِأَنَّهُ يَرْجِع إِلَى الْبَيَاض . وَقَالَ اِبْن عَبَّاس : مَا كُنْت أَدْرِي : مَا يَحُور ؟ حَتَّى سَمِعْت أَعْرَابِيَّة تَدْعُو بُنَيَّة لَهَا : حُورِي , أَيْ اِرْجِعِي إِلَيَّ , فَالْحَوْر فِي كَلَام الْعَرَب الرُّجُوع ; وَمِنْهُ قَوْله عَلَيْهِ السَّلَام : &quot; اللَّهُمَّ إِنِّي أَعُوذ بِك مِنْ الْحَوْر بَعْد الْكَوْر &quot; يَعْنِي : مِنْ الرُّجُوع إِلَى النُّقْصَان بَعْد الزِّيَادَة , وَكَذَلِكَ الْحُوْر بِالضَّمِّ . وَفِي الْمِثْل &quot; حُوْر فِي مَحَارَة &quot; أَيْ نُقْصَان فِي نُقْصَان . يُضْرَب لِلرَّجُلِ إِذَا كَانَ أَمْره يُدْبِر , قَالَ الشَّاعِر : وَاسْتَعْجَلُوا عَنْ خَفِيف الْمَضْغ فَازْدَرَدُوا وَالذَّمّ يَبْقَى وَزَاد الْقَوْم فِي حُوْر وَالْحُور أَيْضًا : الِاسْم مِنْ قَوْلك : طَحَنَتْ الطَّاحِنَة فَمَا أَحَارَتْ شَيْئًا ; أَيْ مَا رَدَّتْ شَيْئًا مِنْ الدَّقِيق . وَالْحُوْر أَيْضًا الْهَلَكَة ; قَالَ الرَّاجِز : فِي بِئْر لَا حُوْر سَرَى وَلَا شَعَر قَالَ أَبُو عُبَيْدَة : أَيْ بِئْر حُوْر , وَ &quot; لَا &quot; زَائِدَة . وَرُوِيَ &quot; بَعْد الْكَوْن &quot; وَمَعْنَاهُ مِنْ اِنْتِشَار الْأَمْر بَعْد تَمَامه . وَسُئِلَ مَعْمَر عَنْ الْحَوْر بَعْد الْكَوْن , فَقَالَ : هُوَ الْكُنْتِيّ . فَقَالَ لَهُ عَبْد الرَّزَّاق : وَمَا الْكُنْتِيّ ؟ فَقَالَ : الرَّجُل يَكُون صَالِحًا ثُمَّ يَتَحَوَّل رَجُل سُوء . قَالَ أَبُو عَمْرو : يُقَال لِلرَّجُلِ إِذَا شَاخَ : كُنْتِيّ , كَأَنَّهُ نُسِبَ إِلَى قَوْله : كُنْت فِي شَبَابِي كَذَا . قَالَ : فَأَصْبَحْت كُنْتِيًّا وَأَصْبَحْت عَاجِنًا وَشَرُّ خِصَال الْمَرْء كُنْت وَعَاجِن عَجَنَ الرَّجُل : إِذَا نَهَضَ مُعْتَمِدًا عَلَى الْأَرْض مِنْ الْكِبَر . وَقَالَ اِبْن الْأَعْرَابِيّ : الْكُنْتِيّ : هُوَ الَّذِي يَقُول : كُنْت شَابًّا , وَكُنْت شُجَاعًا , وَالْكَانِيّ هُوَ الَّذِي يَقُول : كَانَ لِي مَال وَكُنْت أَهَب , وَكَانَ لِي خَيْل وَكُنْت أَرْكَب .';
$t[15] = 'أَيْ لَيْسَ الْأَمْر كَمَا ظَنَّ , بَلْ يَحُور إِلَيْنَا وَيَرْجِع .

قَبْل أَنْ يَخْلُقهُ , عَالِمًا بِأَنَّ مَرْجِعَهُ إِلَيْهِ . وَقِيلَ : بَلَى لَيَحُورَن وَلَيَرْجِعَن . ثُمَّ اِسْتَأْنَفَ فَقَالَ : &quot; إِنَّ رَبّه كَانَ بِهِ بَصِيرًا &quot; مِنْ يَوْم خَلَقَهُ إِلَى أَنْ بَعَثَهُ . وَقِيلَ : عَالِمًا بِمَا سَبَقَ لَهُ مِنْ الشَّقَاء وَالسَّعَادَة .';
$t[16] = 'أَيْ فَأَقْسِم وَ &quot; لَا &quot; صِلَة .

أَيْ بِالْحُمْرَةِ الَّتِي تَكُون عِنْد مَغِيب الشَّمْس حَتَّى تَأْتِي صَلَاة الْعِشَاء الْآخِرَة . قَالَ أَشْهَب وَعَبْد اللَّه بْن الْحَكَم وَيَحْيَى بْن يَحْيَى وَغَيْرهمْ , كَثِير عَدَدهمْ عَنْ مَالِك : الشَّفَق الْحُمْرَة الَّتِي فِي الْمَغْرِب , فَإِذَا ذَهَبَتْ الْحُمْرَة فَقَدْ خَرَجَتْ مِنْ وَقْت الْمَغْرِب وَوَجَبَتْ صَلَاة الْعِشَاء . وَرَوَى بْن وَهْب قَالَ : أَخْبَرَنِي غَيْر وَاحِد عَنْ عَلِيّ اِبْن أَبِي طَالِب وَمُعَاذ بْن جَبَل وَعُبَادَة بْن الصَّامِت وَشَدَّاد بْن أَوْس وَأَبِي هُرَيْرَة : أَنَّ الشَّفَق الْحُمْرَة , وَبِهِ قَالَ مَالِك بْن أَنَس . وَذَكَر غَيْر اِبْن وَهْب مِنْ الصَّحَابَة : عُمَر وَابْن عُمَر وَابْن مَسْعُود وَابْن عَبَّاس وَأَنَسًا وَأَبَا قَتَادَة وَجَابِر بْن عَبْد اللَّه وَابْن الزُّبَيْر , وَمِنْ التَّابِعِينَ : سَعِيد بْن جُبَيْر , وَابْن الْمُسَيِّب وَطَاوُس , وَعَبْد اللَّه بْن دِينَار , وَالزُّهْرِيّ , وَقَالَ بِهِ مِنْ الْفُقَهَاء الْأَوْزَاعِيّ وَمَالِك وَالشَّافِعِيّ وَأَبُو يُوسُف وَأَبُو ثَوْر وَأَبُو عُبَيْدَة وَأَحْمَد وَإِسْحَاق وَقِيلَ : هُوَ الْبَيَاض ; رُوِيَ ذَلِكَ عَنْ اِبْن عَبَّاس وَأَبِي هُرَيْرَة أَيْضًا وَعُمَر بْن عَبْد الْعَزِيز وَالْأَوْزَاعِيّ وَأَبِي حَنِيفَة فِي إِحْدَى الرِّوَايَتَيْنِ عَنْهُ . وَرَوَى أَسَد بْن عَمْرو أَنَّهُ رَجَعَ عَنْهُ . وَرُوِيَ عَنْ اِبْن عُمَر أَيْضًا أَنَّهُ الْبَيَاض وَالِاخْتِيَار الْأَوَّل ; لِأَنَّ أَكْثَر الصَّحَابَة وَالتَّابِعِينَ وَالْفُقَهَاء عَلَيْهِ , وَلِأَنَّ شَوَاهِد كَلَام الْعَرَب وَالِاشْتِقَاق وَالسُّنَّة تَشْهَد لَهُ . قَالَ الْفَرَّاء : سَمِعْت بَعْض الْعَرَب يَقُول لِثَوْبٍ عَلَيْهِ مَصْبُوغ : كَأَنَّهُ الشَّفَق وَكَانَ أَحْمَر , فَهَذَا شَاهِد لِلْحُمْرَةِ ; وَقَالَ الشَّاعِر : وَأَحْمَر اللَّوْن كَمُحْمَرِّ الشَّفَق وَقَالَ آخَر : قُمْ يَا غُلَام أَعْنِي غَيْر مُرْتَبِك عَلَى الزَّمَان بِكَأْسٍ حَشْوُهَا شَفَق وَيُقَال لِلْمَغْرَةِ الشَّفَق . وَفِي الصِّحَاح : الشَّفَق بَقِيَّة ضَوْء الشَّمْس وَحُمْرَتهَا فِي أَوَّل اللَّيْل إِلَى قَرِيب مِنْ الْعَتَمَة . قَالَ الْخَلِيل : الشَّفَق : الْحُمْرَة , مِنْ غُرُوب الشَّمْس إِلَى وَقْت الْعِشَاء الْآخِرَة , إِذَا ذَهَبَ قِيلَ : غَابَ الشَّفَق . ثُمَّ قِيلَ : أَصْل الْكَلِمَة مِنْ رِقَّة الشَّيْء ; يُقَال : شَيْء شَفَق أَيْ لَا تَمَاسُك لَهُ لِرِقَّتِهِ . وَأَشْفَقَ عَلَيْهِ . أَيْ رَقَّ قَلْبه عَلَيْهِ , وَالشَّفَقَة : الِاسْم مِنْ الْإِشْفَاق , وَهُوَ رِقَّة الْقَلْب , وَكَذَلِكَ الشَّفَق ; قَالَ الشَّاعِر : تَهْوَى حَيَاتِي وَأَهْوَى مَوْتهَا شَفَقًا وَالْمَوْت أَكْرَم نَزَّالٍ عَلَى الْحُرَمِ فَالشَّفَق : بَقِيَّة ضَوْء الشَّمْس وَحُمْرَتهَا فَكَأَنَّ تِلْكَ الرِّقَّة عَنْ ضَوْء الشَّمْس . وَزَعَمَ الْحُكَمَاء أَنَّ الْبَيَاض لَا يَغِيب أَصْلًا . وَقَالَ الْخَلِيل : صَعِدْت مَنَارَة الْإِسْكَنْدَرِيَّة فَرَمَقْت الْبَيَاض , فَرَأَيْته يَتَرَدَّد مِنْ أُفُق إِلَى أُفُق وَلَمْ أَرَهُ يَغِيب . وَقَالَ اِبْن أَبِي أُوَيْس : رَأَيْته يَتَمَادَى إِلَى طُلُوع الْفَجْر قَالَ عُلَمَاؤُنَا : فَلَمَّا لَمْ يَتَحَدَّد وَقْته سَقَطَ اِعْتِبَاره . وَفِي سُنَن أَبِي دَاوُد عَنْ النُّعْمَان بْن بَشِير قَالَ : أَنَا أَعْلَمكُمْ بِوَقْتِ صَلَاة الْعِشَاء الْآخِرَة ; كَانَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا لِسُقُوطِ الْقَمَر الثَّالِثَة . وَهَذَا تَحْدِيد , ثُمَّ الْحُكْم مُعَلَّق بِأَوَّلِ الْاسْم . لَا يُقَال : فَيُنْقَض عَلَيْكُمْ بِالْفَجْرِ الْأَوَّل , فَإِنَّا نَقُول الْفَجْر الْأَوَّل لَا يَتَعَلَّق بِهِ حُكْم مِنْ صَلَاة وَلَا إِمْسَاك ; لِأَنَّ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ بَيَّنَ الْفَجْر بِقَوْلِهِ وَفِعْلِهِ فَقَالَ : &quot; وَلَيْسَ الْفَجْر أَنْ تَقُول هَكَذَا - فَرَفَعَ يَده إِلَى فَوْق - وَلَكِنَّ الْفَجْر أَنْ تَقُول هَكَذَا وَبَسَطَهَا &quot; وَقَدْ مَضَى بَيَانه فِي آيَة الصِّيَام مِنْ سُورَة &quot; الْبَقَرَة &quot; , فَلَا مَعْنَى لِلْإِعَادَةِ . وَقَالَ مُجَاهِد : الشَّفَق : النَّهَار كُلّه أَلَا تَرَاهُ قَالَ &quot; وَاللَّيْل وَمَا وَسَقَ &quot; وَقَالَ عِكْرِمَة : مَا بَقِيَ مِنْ النَّهَار . وَالشَّفَق أَيْضًا : الرَّدِيء مِنْ الْأَشْيَاء ; يُقَال : عَطَاء مُشَفَّق أَيْ مُقَلَّل قَالَ الْكُمَيْت : مَلِك أَغَرّ مِنْ الْمُلُوك تَحَلَّبَتْ لِلسَّائِلِينَ يَدَاهُ غَيْر مُشَفِّق';
$t[17] = 'أَيْ جَمَعَ وَضَمَّ وَلَفَّ , وَأَصْله مِنْ سَوْرَة السُّلْطَان وَغَضَبه فَلَوْلَا أَنَّهُ خَرَجَ إِلَى الْعِبَاد مِنْ بَاب الرَّحْمَة مَا تَمَالَكَ الْعِبَاد لِمَجِيئِهِ وَلَكِنْ خَرَجَ مِنْ بَاب الرَّحْمَة فَمَزَحَ بِهَا , فَسَكَنَ الْخَلْق إِلَيْهِ ثُمَّ ابْذَعَرُّوا وَالْتَفُّوا وَانْقَبَضُوا , وَرَجَعَ كُلٌّ إِلَى مَأْوَاهُ فَسَكَنَ فِيهِ مِنْ هَوْله وَحِشًا , وَهُوَ قَوْله تَعَالَى : &quot; وَمِنْ رَحْمَته جَعَلَ لَكُمْ اللَّيْل وَالنَّهَار لِتَسْكُنُوا فِيهِ &quot; [ الْقَصَص : 73 ] أَيْ بِاللَّيْلِ &quot; وَلِتَبْتَغُوا مِنْ فَضْله &quot; [ الْقَصَص : 73 ] أَيْ بِالنَّهَارِ عَلَى مَا تَقَدَّمَ . فَاللَّيْل يَجْمَع وَيَضُمّ مَا كَانَ مُنْتَشِرًا بِالنَّهَارِ فِي تَصَرُّفِهِ . هَذَا مَعْنَى قَوْل اِبْن عَبَّاس وَمُجَاهِد وَمُقَاتِل وَغَيْرهمْ ; قَالَ ضَابِئ بْن الْحَارِث الْبَرْجُمِيّ : فَإِنِّي وَإِيَّاكُمْ وَشَوْقًا إِلَيْكُمْ كَقَابِضِ مَاء لَمْ تَسْقِهِ أَنَامِله يَقُول : لَيْسَ فِي يَده مِنْ ذَلِكَ شَيْء كَمَا أَنَّهُ لَيْسَ فِي يَد الْقَابِض عَلَى الْمَاء شَيْء ; فَإِذَا جَلَّلَ اللَّيْل الْجِبَال وَالْأَشْجَار وَالْبِحَار وَالْأَرْض فَاجْتَمَعَتْ لَهُ , فَقَدْ وَسَقَهَا . وَالْوَسْق : ضَمُّك الشَّيْء بَعْضه إِلَى بَعْض , تَقُول : وَسَقْته أَسِقهُ وَسْقًا . وَمِنْهُ قِيلَ لِلطَّعَامِ الْكَثِير الْمُجْتَمِع : وَسْق , وَهُوَ سِتُّونَ صَاعًا . وَطَعَام مُوسَق : أَيْ مَجْمُوع , وَإِبِل مُسْتَوْسِقَة أَيْ مُجْتَمِعَة ; قَالَ الرَّاجِز : إِنَّ لَنَا قَلَائِصًا حَقَائِقَا مُسْتَوْسِقَات لَوْ يَجِدْنَ سَائِقَا وَقَالَ عِكْرِمَة : &quot; وَمَا وَسَقَ &quot; أَيْ وَمَا سَاقَ مِنْ شَيْء إِلَى حَيْثُ يَأْوِي , فَالْوَسْق بِمَعْنَى الطَّرْد , وَمِنْهُ قِيلَ لِلطَّرِيدَةِ مِنْ الْإِبِل وَالْغَنَم وَالْحُمْر : وَسِيقَة , قَالَ الشَّاعِر : كَمَا قَافَ آثَار الْوَسِيقَة قَائِف وَعَنْ اِبْن عَبَّاس : &quot; وَمَا وَسَقَ &quot; أَيْ وَمَا جَنَّ وَسَتَرَ . وَعَنْهُ أَيْضًا : وَمَا حَمَلَ , وَكُلّ شَيْء حَمَلْته فَقَدْ وَسَقْته , وَالْعَرَب تَقُول : لَا أَفْعَلهُ مَا وَسَقَتْ عَيْنَيَّ الْمَاء , أَيْ حَمَلَتْهُ . وَوَسَقَتْ النَّاقَة تَسِق وَسْقًا : أَيْ حَمَلَتْ وَأَغْلَقَتْ رَحِمهَا عَلَى الْمَاء , فَهِيَ نَاقَة وَاسِق , وَنُوق وِسَاق مِثْل نَائِم وَنِيَام , وَصَاحِب وَصِحَاب , قَالَ بِشْر بْن أَبِي خَازِم : أَلَظَّ بِهِنَّ يَحْدُوهُنَّ حَتَّى تَبَيَّنَتْ الْحِيَال مِنْ الْوِسَاق وَمَوَاسِيق أَيْضًا . وَأَوْسَقْت الْبَعِير : حَمَّلْته حِمْله , وَأَوْسَقَتْ النَّخْلَة : كَثُرَ حَمْلهَا . وَقَالَ يَمَان وَالضَّحَّاك وَمُقَاتِل بْن سُلَيْمَان : حَمَلَ مِنْ الظُّلْمَة . قَالَ مُقَاتِل : أَوْ حَمَلَ مِنْ الْكَوَاكِب . الْقُشَيْرِيّ : وَمَعْنَى حَمَلَ : ضَمَّ وَجَمَعَ , وَاللَّيْل يُجَلِّل بِظُلْمَتِهِ كُلّ شَيْء فَإِذَا جَلَّلَهَا فَقَدْ وَسَقَهَا . وَيَكُون هَذَا الْقَسَم قَسَمًا بِجَمِيعِ الْمَخْلُوقَات , لِاشْتِمَالِ اللَّيْل عَلَيْهَا , كَقَوْلِهِ تَعَالَى : &quot; فَلَا أُقْسِم بِمَا تُبْصِرُونَ وَمَا لَا تُبْصِرُونَ &quot; [ الْحَاقَّة : 38 - 39 ] . وَقَالَ اِبْن جُبَيْر : &quot; وَمَا وَسَقَ &quot; أَيْ وَمَا عُمِلَ فِيهِ , يَعْنِي التَّهَجُّد وَالِاسْتِغْفَار بِالْأَسْحَارِ , قَالَ الشَّاعِر : وَيَوْمًا تَرَانَا صَالِحِينَ وَتَارَة تَقُوم بِنَا كَالْوَاسِقِ الْمُتَلَبِّب أَيْ كَالْعَامِلِ .';
$t[18] = 'أَيْ تَمَّ وَاجْتَمَعَ وَاسْتَوَى . قَالَ الْحَسَن : اتَّسَقَ : أَيْ امْتَلَأَ وَاجْتَمَعَ . اِبْن عَبَّاس : اِسْتَوَى . قَتَادَة : اِسْتَدَارَ . الْفَرَّاء : اِتِّسَاقه : اِمْتِلَاؤُهُ وَاسْتِوَاؤُهُ لَيَالِي الْبَدْر , وَهُوَ اِفْتِعَال مِنْ الْوَسْق الَّذِي هُوَ الْجَمْع , يُقَال : وَسَقْته فَاتَّسَقَ , كَمَا يُقَال : وَصَلْته فَاتَّصَلَ , وَيُقَال : أَمْر فُلَان مُتَّسِق : أَيْ مُجْتَمِع عَلَى الصَّلَاح مُنْتَظِم . وَيُقَال : اِتَّسَقَ الشَّيْء : إِذَا تَتَابَعَ :';
$t[19] = 'قَرَأَ أَبُو عُمَر وَابْن مَسْعُود وَابْن عَبَّاس وَأَبُو الْعَالِيَة وَمَسْرُوق وَأَبُو وَائِل وَمُجَاهِد وَالنَّخَعِيّ وَابْن كَثِير وَحَمْزَة وَالْكِسَائِيّ &quot; لَتَرْكَبَنَّ &quot; بِفَتْحِ الْبَاء خِطَابًا لِلنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ , أَيْ لَتَرْكَبَن يَا مُحَمَّد حَالًا بَعْد حَال , قَالَهُ اِبْن عَبَّاس . الشَّعْبِيّ : لَتَرْكَبَنَّ يَا مُحَمَّد سَمَاء بَعْد سَمَاء , وَدَرَجَة بَعْد دَرَجَة , وَرُتْبَة بَعْد رُتْبَة , فِي الْقُرْبَة مِنْ اللَّه تَعَالَى . اِبْن مَسْعُود : لَتَرْكَبَنَّ السَّمَاء حَالًا بَعْد حَال , يَعْنِي حَالَاتهَا الَّتِي وَصَفَهَا اللَّه تَعَالَى بِهَا مِنْ الِانْشِقَاق وَالطَّيِّ وَكَوْنهَا مَرَّة كَالْمُهْلِ وَمَرَّة كَالدِّهَانِ . وَعَنْ إِبْرَاهِيم عَنْ عَبْد الْأَعْلَى : &quot; طَبَقًا عَنْ طَبَق &quot; قَالَ : السَّمَاء تُقَلَّب حَالًا بَعْد حَال . قَالَ : تَكُون وَرْدَة كَالدِّهَانِ , وَتَكُون كَالْمُهْلِ ; وَقِيلَ : أَيْ لَتَرْكَبَنَّ أَيّهَا الْإِنْسَان حَالًا بَعْد حَال , مِنْ كَوْنِك نُطْفَة ثُمَّ عَلَقَة ثُمَّ مُضْغَة ثُمَّ حَيًّا وَمَيِّتًا وَغَنِيًّا وَفَقِيرًا . فَالْخِطَاب لِلْإِنْسَانِ الْمَذْكُور فِي قَوْله : &quot; يَا أَيُّهَا الْإِنْسَان إِنَّك كَادِح &quot; هُوَ اِسْم لِلْجِنْسِ , وَمَعْنَاهُ النَّاس . وَقَرَأَ الْبَاقُونَ &quot; لَتَرْكَبُنَّ &quot; بِضَمِّ الْبَاء , خِطَابًا لِلنَّاسِ , وَاخْتَارَهُ أَبُو عُبَيْد وَأَبُو حَاتِم , قَالَ : لِأَنَّ الْمَعْنَى بِالنَّاسِ أَشْبَه مِنْهُ بِالنَّبِيِّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ , لِمَا ذُكِرَ قَبْل هَذِهِ الْآيَة فَمَنْ أُوتِيَ كِتَابه بِيَمِينِهِ وَمَنْ أُوتِيَ كِتَابه بِشِمَالِهِ . أَيْ لَتَرْكَبُنَّ حَالًا بَعْد حَال مِنْ شَدَائِد الْقِيَامَة , أَوْ لَتَرْكَبُنَّ سُنَّة مَنْ كَانَ قَبْلَكُمْ فِي التَّكْذِيب وَاخْتِلَاق عَلَى الْأَنْبِيَاء . قُلْت : وَكُلّه مُرَاد , وَقَدْ جَاءَتْ بِذَلِكَ أَحَادِيث , فَرَوَى أَبُو نُعَيْم الْحَافِظ عَنْ جَعْفَر بْن مُحَمَّد بْن عَلِيّ عَنْ جَابِر رَضِيَ اللَّه عَنْهُ , قَالَ سَمِعْت رَسُول صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَقُول : ( إِنَّ اِبْن آدَم لَفِي غَفْلَة عَمَّا خَلَقَهُ اللَّه عَزَّ وَجَلَّ ; إِنَّ اللَّه لَا إِلَه غَيْره إِذَا أَرَادَ خَلْقه قَالَ لِلْمَلَكِ اكْتُبْ رِزْقَهُ وَأَثَره وَأَجَله , وَاكْتُبْ شَقِيًّا أَوْ سَعِيدًا , ثُمَّ يَرْتَفِع ذَلِكَ الْمَلَك , وَيَبْعَث اللَّه مَلَكًا آخَر فَيُحَفِّظهُ حَتَّى يُدْرِك , ثُمَّ يَبْعَث اللَّه مَلَكَيْنِ يَكْتُبَانِ حَسَنَاته وَسَيِّئَاته , فَإِذَا جَاءَهُ الْمَوْت اِرْتَفَعَ ذَانِك الْمَلَكَانِ , ثُمَّ جَاءَهُ مَلَك الْمَوْت عَلَيْهِ السَّلَام فَيَقْبِض رُوحه , فَإِذَا أُدْخِلَ حُفْرَتَهُ رُدَّ الرُّوح فِي جَسَده , ثُمَّ يَرْتَفِع مَلَك الْمَوْت , ثُمَّ جَاءَهُ مَلَكَا الْقَبْر فَامْتَحَنَاهُ , ثُمَّ يَرْتَفِعَانِ , فَإِذَا قَامَتْ السَّاعَة اِنْحَطَّ عَلَيْهِ مَلَك الْحَسَنَات وَمَلَك السَّيِّئَات , فَأَنْشَطَا كِتَابًا مَعْقُودًا فِي عُنُقه , ثُمَّ حَضَرَا مَعَهُ , وَاحِد سَائِق وَالْآخَر شَهِيد ) ثُمَّ قَالَ اللَّه عَزَّ وَجَلَّ &quot; لَقَدْ كُنْت فِي غَفْلَة مِنْ هَذَا فَكَشَفْنَا عَنْك غِطَاءَك , فَبَصَرُك الْيَوْم حَدِيدٌ &quot; [ ق : 22 ] . قَالَ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : &quot; لَتَرْكَبُنَّ طَبَقًا عَنْ طَبَق &quot; قَالَ : ( حَالًا بَعْد حَال ) ثُمَّ قَالَ النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( إِنَّ قُدَّامَكُمْ أَمْرًا عَظِيمًا فَاسْتَعِينُوا بِاَللَّهِ الْعَظِيم ) فَقَدْ اِشْتَمَلَ هَذَا الْحَدِيث عَلَى أَحْوَال تَعْتَرِي الْإِنْسَان , مِنْ حِين يُخْلَق إِلَى حِين يُبْعَث , وَكُلّه شِدَّة بَعْد شِدَّة , حَيَاة ثُمَّ مَوْت , ثُمَّ بَعْث ثُمَّ جَزَاء , وَفِي كُلّ حَال مِنْ هَذِهِ شَدَائِد . وَقَالَ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : ( لَتَرْكَبُنَّ سُنَن مَنْ قَبْلَكُمْ شِبْرًا بِشِبْرٍ , وَذِرَاعًا بِذِرَاعٍ , حَتَّى لَوْ دَخَلُوا جُحْر ضَبٍّ لَدَخَلْتُمُوهُ ) قَالُوا : يَا رَسُول اللَّه , الْيَهُود وَالنَّصَارَى ؟ قَالَ : فَمَنْ ؟ خَرَّجَهُ الْبُخَارِيّ : وَأَمَّا أَقْوَال الْمُفَسِّرِينَ , فَقَالَ عِكْرِمَة : حَالًا بَعْد حَال , فَطِيمًا بَعْد رَضِيع , وَشَيْخًا بَعْد شَبَاب , قَالَ الشَّاعِر : كَذَلِكَ الْمَرْء إِنْ يُنْسَأْ لَهُ أَجَل يَرْكَبْ عَلَى طَبَقٍ مِنْ بَعْدِهِ طَبَق وَعَنْ مَكْحُول : كُلّ عِشْرِينَ عَامًا تَجِدُونَ أَمْرًا لَمْ تَكُونُوا عَلَيْهِ : وَقَالَ الْحَسَن : أَمْرًا بَعْد أَمْرٍ , رَخَاء بَعْد شِدَّة , وَشِدَّة بَعْد رَخَاء , وَغِنًى بَعْد فَقْر , وَفَقْرًا بَعْد غِنًى , وَصِحَّة بَعْد سَقَم , وَسَقَمًا بَعْد صِحَّة : سَعِيد بْن جُبَيْر : مَنْزِلَة بَعْد مَنْزِلَة , قَوْم كَانُوا فِي الدُّنْيَا مُتَّضِعِينَ فَارْتَفَعُوا فِي الْآخِرَة , وَقَوْم كَانُوا فِي الدُّنْيَا مُرْتَفِعِينَ فَاتَّضَعُوا فِي الْآخِرَة : وَقِيلَ : مَنْزِلَة عَنْ مَنْزِلَة , وَطَبَقًا عَنْ طَبَق , وَذَلِكَ , أَنَّ مَنْ كَانَ عَلَى صَلَاح دَعَاهُ إِلَى صَلَاح فَوْقه , وَمَنْ كَانَ عَلَى فَسَاد دَعَاهُ إِلَى فَسَاد فَوْقه ; لِأَنَّ كُلّ شَيْء يَجْرِي إِلَى شَكْله : اِبْن زَيْد : وَلَتَصِيرُنَّ مِنْ طَبَق الدُّنْيَا إِلَى طَبَق الْآخِرَة : وَقَالَ اِبْن عَبَّاس : الشَّدَائِد وَالْأَهْوَال : الْمَوْت , ثُمَّ الْبَعْث , ثُمَّ الْعَرْض , وَالْعَرَب تَقُول لِمَنْ وَقَعَ فِي أَمْر شَدِيد : وَقَعَ فِي بَنَات طَبَق , وَإِحْدَى بَنَات طَبَق , وَمِنْهُ قِيلَ لِلدَّاهِيَةِ الشَّدِيدَة : أُمّ طَبَق , وَإِحْدَى بَنَات طَبَق : وَأَصْلهَا مِنْ الْحَيَّات , إِذْ يُقَال : لِلْحَيَّةِ أُمّ طَبَق لِتَحْوِيهَا : وَالطَّبَق فِي اللُّغَة : الْحَال كَمَا وَصَفْنَا , قَالَ الْأَقْرَع بْن حَابِس التَّمِيمِيّ : إِنِّي اِمْرُؤُ قَدْ حَلَبْت الدَّهْر أَشْطُرَهُ وَسَاقَنِي طَبَق مِنْهُ إِلَى طَبَق وَغَدًا أَدَلّ دَلِيل عَلَى حُدُوث الْعَالَم , وَإِثْبَات الصَّانِع , قَالَتْ الْحُكَمَاء : مَنْ كَانَ الْيَوْم عَلَى حَالَة , وَغَدًا عَلَى حَالَة أُخْرَى فَلْيَعْلَمْ أَنَّ تَدْبِيره إِلَى سِوَاهُ : وَقِيلَ لِأَبِي بَكْر الْوَرَّاق : مَا الدَّلِيل عَلَى أَنَّ لِهَذَا الْعَالَم صَانِعًا ؟ فَقَالَ : تَحْوِيل الْحَالَات , وَعَجْز الْقُوَّة , وَضَعْف الْأَرْكَان , وَقَهْر النِّيَّة : وَنَسْخ الْعَزِيمَة : وَيُقَال : أَتَانَا طَبَق مِنْ النَّاس وَطَبَق مِنْ الْجَرَاد : أَيْ جَمَاعَة : وَقَوْل الْعَبَّاس فِي مَدْح النَّبِيّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ : تَنْقُل مِنْ صَالِبٍ إِلَى رَحِم إِذَا مَضَى عَالَم بَدَا طَبَق أَيْ قَرْن مِنْ النَّاس . يَكُون طِبَاق الْأَرْض أَيْ مِلْأَهَا . وَالطَّبَق أَيْضًا : عَظْم رَقِيق يَفْصِل بَيْن الْفَقَارَيْنِ وَيُقَال : مَضَى طَبَق مِنْ اللَّيْل , وَطَبَق مِنْ النَّهَار : أَيْ مُعْظَم مِنْهُ . وَالطَّبَق : وَاحِد الْأَطْبَاق , فَهُوَ مُشْتَرَك . وَقُرِئَ &quot; لَتَرْكَبِنَّ &quot; بِكَسْرِ الْبَاء , عَلَى خِطَاب النَّفْس وَ &quot; لَيَرْكَبَنَّ &quot; بِالْيَاءِ عَلَى لَيَرْكَبَنَّ الْإِنْسَان . وَ &quot; عَنْ طَبَق &quot; فِي مَحَلّ نَصْب عَلَى أَنَّهُ صِفَة لِـ &quot; طَبَقًا &quot; أَيْ طَبَقًا مُجَاوِزًا لِطَبَقٍ . أَوْ حَال مِنْ الضَّمِير فِي &quot; لَتَرْكَبُنَّ &quot; أَيْ لَتَرْكَبُنَّ طَبَقًا مُجَاوِزِينَ لِطَبَقٍ , أَوْ مُجَاوِزًا أَوْ مُجَاوَزَة عَلَى حَسَب الْقِرَاءَة .';
$t[20] = 'يَعْنِي أَيّ شَيْء يَمْنَعهُمْ مِنْ الْإِيمَان بَعْدَمَا وَضَحَتْ لَهُمْ الْآيَات وَقَامَتْ الدَّلَالَات . وَهَذَا اِسْتِفْهَام إِنْكَار . وَقِيلَ : تَعَجُّب أَيْ اِعْجَبُوا مِنْهُمْ فِي تَرْك الْإِيمَان مَعَ هَذِهِ الْآيَات .';
$t[21] = 'أَيْ لَا يُصَلُّونَ . وَفِي الصَّحِيح : أَنَّ أَبَا هُرَيْرَة قَرَأَ &quot; إِذَا السَّمَاء انْشَقَّتْ &quot; فَسَجَدَ فِيهَا , فَلَمَّا انْصَرَفَ أَخْبَرَهُمْ أَنَّ رَسُول اللَّه صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ سَجَدَ فِيهَا . وَقَدْ قَالَ مَالِك : إِنَّهَا لَيْسَتْ مِنْ عَزَائِم السُّجُود ; لِأَنَّ [ الْمَعْنَى ] لَا يُذْعِنُونَ وَلَا يُطِيعُونَ فِي الْعَمَل بِوَاجِبَاتِهِ . اِبْن الْعَرَبِيّ : وَالصَّحِيح أَنَّهَا مِنْهُ , وَهِيَ رِوَايَة الْمَدَنِيِّينَ عَنْهُ , وَقَدْ اعْتَضَدَ فِيهَا الْقُرْآن وَالسُّنَّة . قَالَ اِبْن الْعَرَبِيّ : لَمَّا أَمَمْت بِالنَّاسِ تَرَكْت قِرَاءَتهَا ; لِأَنِّي إِنْ سَجَدْت أَنْكَرُوهُ , وَإِنْ تَرَكْتهَا كَانَ تَقْصِيرًا مِنِّي , فَاجْتَنَبْتهَا إِلَّا إِذَا صَلَّيْت وَحْدِي . وَهَذَا تَحْقِيق وَعْد الصَّادِق بِأَنْ يَكُون الْمَعْرُوف مُنْكَرًا , وَالْمُنْكَر مَعْرُوفًا ; وَقَدْ قَالَ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ لِعَائِشَة : ( لَوْلَا حِدْثَان قَوْمك بِالْكُفْرِ لَهَدَمْت الْبَيْت , وَلَرَدَدْته عَلَى قَوَاعِد إِبْرَاهِيم ) . وَلَقَدْ كَانَ شَيْخُنَا أَبُو بَكْر الْفِهْرِيّ يَرْفَع يَدَيْهِ عِنْد الرُّكُوع , وَعِنْد الرَّفْع مِنْهُ , وَهُوَ مَذْهَب مَالِك وَالشَّافِعِيّ وَيَفْعَلهُ الشِّيعَة , فَحَضَرَ عِنْدِي يَوْمًا فِي مَحْرَس اِبْن الشَّوَّاء بِالثَّغْرِ - مَوْضِع تَدْرِيسِي - عِنْد صَلَاة الظُّهْر , وَدَخَلَ الْمَسْجِد مِنْ الْمَحْرَس الْمَذْكُور , فَتَقَدَّمَ إِلَى الصَّفّ وَأَنَا فِي مُؤَخَّره قَاعِدًا عَلَى طَاقَات الْبَحْر , أَتَنَسَّم الرِّيح مِنْ شِدَّة الْحَرّ , وَمَعِي فِي صَفّ وَاحِد أَبُو ثمنة رَئِيس الْبَحْر وَقَائِده , مَعَ نَفَر مِنْ أَصْحَابه يَنْتَظِر الصَّلَاة , وَيَتَطَلَّع عَلَى مَرَاكِب تَخْت الْمِينَاء , فَلَمَّا رَفَعَ الشَّيْخ يَدَيْهِ فِي الرُّكُوع وَفِي رَفْع الرَّأْس مِنْهُ قَالَ أَبُو ثمنة وَأَصْحَابه : أَلَا تَرَوْنَ إِلَى هَذَا الْمَشْرِقِيّ كَيْف دَخَلَ مَسْجِدنَا ؟ فَقُومُوا إِلَيْهِ فَاقْتُلُوهُ وَارْمُوا بِهِ إِلَى الْبَحْر , فَلَا يَرَاكُمْ أَحَد . فَطَارَ قَلْبِي مِنْ بَيْن جَوَانِحِي وَقُلْت : سُبْحَان اللَّه هَذَا الطُّرْطُوشِيّ فَقِيهِ الْوَقْت . فَقَالُوا لِي : وَلِمَ يَرْفَع يَدَيْهِ ؟ فَقُلْت : كَذَلِكَ كَانَ النَّبِيُّ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ يَفْعَل , وَهَذَا مَذْهَب مَالِك , فِي رِوَايَة أَهْل الْمَدِينَة عَنْهُ . وَجَعَلْت أُسْكِنُهُمْ وَأُسْكِتُهُمْ حَتَّى فَرَغَ مِنْ صَلَاته , وَقُمْت مَعَهُ إِلَى الْمَسْكَن مِنْ الْمَحْرَس , وَرَأَى تَغَيُّرَ وَجْهِي , فَأَنْكَرَهُ , وَسَأَلَنِي فَأَعْلَمْته , فَضَحِكَ وَقَالَ : وَمِنْ أَيْنَ لِي أَنْ أُقْتَل عَلَى سُنَّة ؟ فَقُلْت لَهُ : وَلَا يَحِلّ لَك هَذَا , فَإِنَّك بَيْن قَوْم إِنْ قُمْت بِهَا قَامُوا عَلَيْك وَرُبَّمَا ذَهَبَ دَمُك . فَقَالَ : دَعْ هَذَا الْكَلَام , وَخُذْ فِي غَيْره .';
$t[22] = 'مُحَمَّدًا صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ وَمَا جَاءَ بِهِ . وَقَالَ مُقَاتِل : نَزَلْت فِي بَنِي عَمْرو بْن عُمَيْر وَكَانُوا أَرْبَعَة , فَأَسْلَمَ آثْنَانِ مِنْهُمْ . وَقِيلَ : هِيَ فِي جَمِيع الْكُفَّار .';
$t[23] = 'أَيْ بِمَا يُضْمِرُونَهُ فِي أَنْفُسِهِمْ مِنْ التَّكْذِيب . كَذَا رَوَى الضَّحَّاك عَنْ اِبْن عَبَّاس . وَقَالَ مُجَاهِد : يَكْتُمُونَ مِنْ أَفْعَالِهِمْ . اِبْن زَيْد : يَجْمَعُونَ مِنْ الْأَعْمَال الصَّالِحَة وَالسَّيِّئَة ; مَأْخُوذ مِنْ الْوِعَاء الَّذِي يُجْمَع مَا فِيهِ ; يُقَال : أَوَعَيْت الزَّاد وَالْمَتَاع : إِذَا جَعَلْته فِي الْوِعَاء ; قَالَ الشَّاعِر : الْخَيْر أَبْقَى وَإِنْ طَالَ الزَّمَان بِهِ وَالشَّرّ أَخْبَث مَا أَوَعَيْت مِنْ زَاد وَوَعَاهُ أَيْ حَفِظَهُ ; تَقُول : وَعَيْت الْحَدِيث أَعِيه وَعْيًا , وَأُذُن وَاعِيَة . وَقَدْ تَقَدَّمَ .';
$t[24] = 'أَيْ مُوجِع فِي جَهَنَّم عَلَى تَكْذِيبهمْ . أَيْ أَجْعَل ذَلِكَ بِمَنْزِلَةِ الْبِشَارَة .';
$t[25] = 'اِسْتِثْنَاء مُنْقَطِع , كَأَنَّهُ قَالَ : لَكِنْ الَّذِينَ صَدَّقُوا بِشَهَادَةِ أَنْ لَا إِلَه إِلَّا اللَّه وَأَنَّ مُحَمَّدًا رَسُول اللَّه , وَعَمِلُوا الصَّالِحَات , أَيْ أَدَّوْا الْفَرَائِض الْمَفْرُوضَة عَلَيْهِمْ.

&quot; لَهُمْ أَجْر &quot; أَيْ ثَوَاب &quot; غَيْر مَمْنُون &quot; أَيْ غَيْر مَنْقُوص وَلَا مَقْطُوع ; يُقَال : مَنَنْت الْحَبْل : إِذَا قَطَعْته . وَقَدْ تَقَدَّمَ . &quot; لَهُمْ أَجْر غَيْر مَمْنُون &quot; سَأَلَ نَافِع بْن الْأَزْرَق اِبْن عَبَّاس عَنْ قَوْله : فَقَالَ : غَيْر مَقْطُوع . فَقَالَ : هَلْ تَعْرِف ذَلِكَ الْعَرَب ؟ قَالَ : نَعَمْ قَدْ عَرَفَهُ أَخُو يَشْكُر حَيْثُ يَقُول : فَتَرَى خَلْفهنَّ مِنْ سُرْعَة الرَّجْ عِ مَنِينًا كَأَنَّهُ أَهْبَاء قَالَ الْمُبَرِّد : الْمَنِين : الْغُبَار ; لِأَنَّهَا تَقْطَعهُ وَرَاءَهَا . وَكُلّ ضَعِيف مَنِين وَمَمْنُون . وَقِيلَ : &quot; غَيْر مَمْنُون &quot; لَا يُمَنَّ عَلَيْهِمْ بِهِ . وَذَكَرَ نَاس مِنْ أَهْل الْعِلْم أَنَّ قَوْله : &quot; إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَات &quot; لَيْسَ اِسْتِئْنَاء , وَإِنَّمَا هُوَ بِمَعْنَى الْوَاو , كَأَنَّهُ قَالَ : وَاَلَّذِينَ آمَنُوا . وَقَدْ مَضَى فِي &quot; الْبَقَرَة &quot; الْقَوْل فِيهِ وَالْحَمْد لِلَّهِ . تَمَّتْ سُورَة الِانْشِقَاق .';
?>